fn browser_runtime_array_from_source() -> String {
    let source = kali_common::array_from_alias_inventory_source();
    format!(
        "const values = [1, 2];\n{}\n",
        source
            .trim_end_matches(';')
            .split("; ")
            .map(|alias| format!(
                "for (const value of {alias}(values)) {{\n  console.log(value);\n}}"
            ))
            .collect::<Vec<_>>()
            .join("\n")
    )
}

