fn object_property_deletion_semantics_source() -> &'static str {
    r#"const obj = { a: 1, b: 2 };
if (!('a' in obj) || !('b' in obj)) {
  throw 'missing property';
}
if (delete obj.a !== true) {
  throw 'unexpected delete result';
}
if ('a' in obj) {
  throw 'delete failed';
}
"#
}

